// Patches the platform folders generated by `flutter create` so local
// notifications, boot rescheduling and exact alarms work.
//
// Safe to run more than once — every patch checks before applying.
//
//   dart run tool/setup.dart
import 'dart:io';

void main() {
  var ok = true;
  ok &= _patchManifest();
  ok &= _patchGradle();
  _patchAppDelegate();
  _patchInfoPlist();
  _writeNotificationIcon();
  stdout.writeln(ok
      ? '\n✅ Momentum platform setup complete. Run: flutter run'
      : '\n⚠️  Some steps could not be applied automatically — see messages above.');
}

bool _patchManifest() {
  final f = File('android/app/src/main/AndroidManifest.xml');
  if (!f.existsSync()) {
    stderr.writeln('✗ AndroidManifest.xml not found. Run `flutter create .` first.');
    return false;
  }
  var s = f.readAsStringSync();

  const perms = [
    'android.permission.POST_NOTIFICATIONS',
    'android.permission.RECEIVE_BOOT_COMPLETED',
    'android.permission.VIBRATE',
    'android.permission.SCHEDULE_EXACT_ALARM',
  ];
  final missing = perms.where((p) => !s.contains('"$p"')).toList();
  if (missing.isNotEmpty) {
    final lines = missing.map((p) => '    <uses-permission android:name="$p"/>').join('\n');
    s = s.replaceFirst('<application', '$lines\n\n    <application');
  }

  if (!s.contains('ScheduledNotificationReceiver')) {
    const receivers = '''
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
    ''';
    s = s.replaceFirst('</application>', '$receivers</application>');
  }

  if (!s.contains('android.intent.action.VIEW')) {
    const queries = '''
    <queries>
        <intent>
            <action android:name="android.intent.action.VIEW" />
            <data android:scheme="https" />
        </intent>
    </queries>
''';
    s = s.replaceFirst('</manifest>', '$queries</manifest>');
  }

  s = s.replaceFirst(RegExp(r'android:label="[^"]*"'), 'android:label="Momentum"');
  f.writeAsStringSync(s);
  stdout.writeln('✓ AndroidManifest.xml patched');
  return true;
}

bool _patchGradle() {
  final kts = File('android/app/build.gradle.kts');
  final groovy = File('android/app/build.gradle');
  const lib = 'com.android.tools:desugar_jdk_libs:2.1.4';

  if (kts.existsSync()) {
    var s = kts.readAsStringSync();
    if (!s.contains('isCoreLibraryDesugaringEnabled')) {
      s = s.replaceFirst(
          'compileOptions {', 'compileOptions {\n        isCoreLibraryDesugaringEnabled = true');
    }
    if (!s.contains('desugar_jdk_libs')) {
      s += '\ndependencies {\n    coreLibraryDesugaring("$lib")\n}\n';
    }
    kts.writeAsStringSync(s);
    stdout.writeln('✓ build.gradle.kts patched (core library desugaring)');
    return true;
  }

  if (groovy.existsSync()) {
    var s = groovy.readAsStringSync();
    if (!s.contains('coreLibraryDesugaringEnabled')) {
      s = s.replaceFirst(
          'compileOptions {', 'compileOptions {\n        coreLibraryDesugaringEnabled true');
    }
    if (!s.contains('desugar_jdk_libs')) {
      s += "\ndependencies {\n    coreLibraryDesugaring '$lib'\n}\n";
    }
    groovy.writeAsStringSync(s);
    stdout.writeln('✓ build.gradle patched (core library desugaring)');
    return true;
  }

  stderr.writeln('✗ android/app/build.gradle(.kts) not found.');
  return false;
}

void _patchAppDelegate() {
  final f = File('ios/Runner/AppDelegate.swift');
  if (!f.existsSync()) {
    stdout.writeln('• iOS folder not found — skipping (fine if you only build Android).');
    return;
  }
  var s = f.readAsStringSync();
  if (s.contains('UNUserNotificationCenter')) {
    stdout.writeln('✓ AppDelegate.swift already patched');
    return;
  }
  if (!s.contains('import UserNotifications')) {
    s = s.replaceFirst('import UIKit', 'import UIKit\nimport UserNotifications');
  }
  final line = RegExp(r'^.*GeneratedPluginRegistrant\.register\(.*$', multiLine: true)
      .firstMatch(s);
  if (line == null) {
    stdout.writeln('• Could not find plugin registration in AppDelegate.swift — '
        'foreground iOS banners may not show. Everything else works.');
    return;
  }
  const delegate = '\n    UNUserNotificationCenter.current().delegate = '
      'self as? UNUserNotificationCenterDelegate';
  s = s.replaceRange(line.end, line.end, delegate);
  f.writeAsStringSync(s);
  stdout.writeln('✓ AppDelegate.swift patched (foreground notifications)');
}

/// Declares English + Russian so iOS shows the app (and App Store listing)
/// in the user's language.
void _patchInfoPlist() {
  final f = File('ios/Runner/Info.plist');
  if (!f.existsSync()) return;
  var s = f.readAsStringSync();
  s = s.replaceFirstMapped(
      RegExp(r'(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)'),
      (m) => '${m[1]}Momentum${m[2]}');
  f.writeAsStringSync(s);
  if (s.contains('CFBundleLocalizations')) {
    stdout.writeln('✓ Info.plist already declares languages');
    return;
  }
  const entry = '\t<key>CFBundleLocalizations</key>\n'
      '\t<array>\n\t\t<string>en</string>\n\t\t<string>ru</string>\n\t</array>\n';
  final i = s.lastIndexOf('</dict>');
  if (i == -1) return;
  s = s.replaceRange(i, i, entry);
  f.writeAsStringSync(s);
  stdout.writeln('✓ Info.plist patched (English + Russian)');
}

/// Android shows notification icons as a white silhouette, so the full-colour
/// launcher icon would appear as a white square. This writes a proper
/// monochrome check-mark icon and keeps it from being stripped in release builds.
void _writeNotificationIcon() {
  final res = Directory('android/app/src/main/res');
  if (!res.existsSync()) return;

  final drawable = Directory('${res.path}/drawable')..createSync(recursive: true);
  File('${drawable.path}/ic_notification.xml').writeAsStringSync('''
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="24dp"
    android:height="24dp"
    android:viewportWidth="24"
    android:viewportHeight="24">
    <path
        android:fillColor="#FFFFFFFF"
        android:pathData="M12,2C6.48,2 2,6.48 2,12s4.48,10 10,10 10,-4.48 10,-10S17.52,2 12,2zM10.2,16.6l-4.3,-4.3 1.41,-1.41 2.89,2.88 6.49,-6.49 1.41,1.42z" />
</vector>
''');

  final raw = Directory('${res.path}/raw')..createSync(recursive: true);
  File('${raw.path}/keep.xml').writeAsStringSync('''<?xml version="1.0" encoding="utf-8"?>
<resources xmlns:tools="http://schemas.android.com/tools"
    tools:keep="@drawable/ic_notification" />
''');
  stdout.writeln('✓ Notification icon written (drawable/ic_notification.xml)');
}
